document.addEventListener("DOMContentLoaded",()=>{const e=document.getElementById("mem-input-value"),t=document.getElementById("mem-from-unit"),n=document.getElementById("mem-to-unit"),s=document.getElementById("mem-result"),o=document.getElementById("mem-result-full"),i={bit:.125,B:1,KB:1e3,MB:1e3**2,GB:1e3**3,TB:1e3**4,KiB:1024,MiB:1024**2,GiB:1024**3,TiB:1024**4};function a(e){return e===0?"0":e<.001||e>1e12?e.toExponential(4):parseFloat(e.toFixed(6)).toString()}function r(){const r=parseFloat(e.value);if(isNaN(r)||r===0){s.textContent="0",o.textContent="";return}const l=i[t.value],d=i[n.value],c=r*l,u=c/d;s.textContent=a(u),o.textContent=`= ${c.toLocaleString("pt-BR")} Bytes`}[e,t,n].forEach(e=>{e.addEventListener("input",r)})})